updateCurrentTime(container: HTMLElement, timeFilter?: (hour: number) => TimeFilterResult): void {
  container.querySelectorAll(".tg-now-line").forEach(line => line.remove());
  const now = new Date(), date = this.adapter.format(this.adapter.create(now), this.dateFormats.date);
  const column = Array.from(container.querySelectorAll<HTMLElement>(".tg-day-column")).find(col => col.dataset["date"] === date);
  const slots = this.engine.generateTimeSlots(timeFilter), index = slots.findIndex(slot => slot.hour === now.getHours());
  if (!column || index < 0) return;
  const line = createElement("div", "tg-now-line");
  line.setAttribute("aria-label", `${String(now.getHours()).padStart(2, "0")}:${String(now.getMinutes()).padStart(2, "0")}`);
  line.style.top = `${(index + now.getMinutes() / 60) * this.theme.cellHeight}px`;
  column.appendChild(line);
}

